            function createFbDetailPerdmenOso(content, fb, formOpt) {
                formOpt.forEach((o) => {
                    if (["dat_zmena", "zmenu_prov_txt"].includes(o.field_id) && content["IsNewRecord"])
                        return; //když je nový záznam, tak nebudu přidávat
                    const validators = [];
                    if (o.priz_pov_bool)
                        validators.push(new Gordic.Validators.Required());
                    fb.addRow({ name: "row_" + o.field_id, label: o.field_id === "priz_splneno" ? "" : o.field_label ?? "", required: o.priz_pov_bool ?? false });
                    switch (o.field_id) {
                        case "cil":
                        case "poznamka":
                        case "zmenu_prov_txt":
                            fb.addField("gstringbox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                            });
                            break;
                        case "komentar":
                            fb.addField("gstringbox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                rows: 2,
                            });
                            break;
                        case "dat_od":
                            fb.addField("gdatebox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                minValue: WebControls.dateMinValue(),
                                maxValue: WebControls.dateMaxValue(),
                                model: `${o.field_id}=value, dat_konani=value`,
                            });
                            break;
                        case "dat_do":
                            fb.addField("gdatebox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                minValue: WebControls.dateMinValue(),
                                maxValue: WebControls.dateMaxValue(),
                            });
                            break;
                        case "dat_zmena":
                            fb.addField("gdatebox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                minValue: WebControls.dateMinValue(),
                                maxValue: WebControls.dateMaxValue(),
                                valueType: "datetime",
                            });
                            break;
                        case "dat_konani": {
                            //TODO: přidat change, pokud je rok, tak nastavit začátek roku
                            let format = "dd.MM.yyyy";
                            let model = "dat_konani=value,dat_od<=value,dat_do<=value";
                            let placeholder = "D.M.YYYY";
                            switch (content["druh"] ?? WebControls.DruhTrvaniPrubehuMen.den) {
                                case WebControls.DruhTrvaniPrubehuMen.mesic:
                                    format = "MM.yyyy";
                                    placeholder = "Měsíc a rok";
                                    model = "dat_konani=value,dat_od<=value";
                                    break;
                                case WebControls.DruhTrvaniPrubehuMen.rok:
                                    format = "yyyy";
                                    placeholder = "Rok";
                                    model = "dat_konani=value,dat_od<=value";
                                    break;
                                case WebControls.DruhTrvaniPrubehuMen.den:
                                default:
                                    format = "dd.MM.yyyy";
                                    model = "dat_konani=value,dat_od<=value,dat_do<=value";
                                    placeholder = "D.M.YYYY";
                                    break;
                            }
                            fb.addField("gdatebox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                format: format,
                                model: model,
                                placeholder: placeholder,
                                minValue: WebControls.dateMinValue(),
                                maxValue: WebControls.dateMaxValue(),
                            });
                            break;
                        }
                        case "delka":
                            fb.addField("gnumberbox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                minValue: 0,
                                decimals: 2,
                            });
                            break;
                        case "priz_splneno":
                            fb.addField("gcheck", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                label: o.field_label ?? "",
                                modelValueTransform: {
                                    apply: function (modelValue) {
                                        return modelValue === 1;
                                    },
                                    collect: function (fieldValue) {
                                        return fieldValue === true ? 1 : 0;
                                    },
                                },
                            });
                            break;
                    }
                });
                return fb;
            }
