            function createFbDetailPerdpvjTab(content, fb, formOpt) {
                formOpt.forEach((o) => {
                    const validators = [];
                    if (o.priz_pov_bool)
                        validators.push(new Gordic.Validators.Required());
                    if (!["check_vraceni"].includes(o.field_id))
                        fb.addRow({ name: "row_" + o.field_id, label: o.field_label ?? "", required: o.priz_pov_bool ?? false });
                    else
                        fb.addRow({ name: "row_" + o.field_id, /*label: o!.field_label ?? "",*/ required: o.priz_pov_bool ?? false });
                    switch (o.field_id) {
                        case "check_vraceni":
                            fb.addField("gcheck", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                label: o.field_label ?? "",
                                modelValueTransform: {
                                    apply: function (modelValue) {
                                        return modelValue === 1;
                                    },
                                    //collect: function (fieldValue) {
                                    //    return fieldValue === true ? 1 : 0;
                                    //},
                                },
                                model: function (operation, dto, modelOptions) {
                                    switch (operation) {
                                        case "apply": {
                                            const field = $(this);
                                            const form = field.gform();
                                            const checkValue = dto.dat_vraceni != null;
                                            $(this).gfield("setValue", checkValue);
                                            form.findFields("dat_vraceni,c_vracena,oduvodneni_uk").gfield("option", "disabled", !checkValue);
                                            return;
                                        }
                                        //case "collect":
                                        //    dto.checkValue = $(this).gfield("getValue") === true ? 1 : 0;
                                        //    return;
                                        default:
                                            return "checkValue";
                                    }
                                },
                                change: (ev, obj) => {
                                    const form = $(ev.target).gform();
                                    form.findFields("dat_vraceni,c_vracena,oduvodneni_uk").gfield("option", "disabled", !obj.value);
                                },
                            });
                            break;
                        case "c":
                        case "c_vracena":
                            fb.addField("gnumberbox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                decimals: 2,
                                defaultValue: null,
                            });
                            break;
                        case "select_c":
                            fb.addField("gselectbox", Gordic.Prefabs.Select.gCisReaderNaborPrispevek(), {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                model: "c=c_prisp",
                                dropdown: false,
                                serverFilters: { prisp: { o: "!=", v: 0 } },
                            });
                            break;
                        case "ixs_tks":
                            fb.addField("gselectbox", Gordic.Prefabs.Select.gCisReaderPamsslo(), {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                model: "ixs_tks=ixs_tks,slozka_mzdy=slozka_mzdy,slozka_mzdy_txt<=slozka_mzdy_txt",
                                dropdown: false,
                                serverFilters: {
                                    dat_platnost: new Gordic.Forms.Dependency("dat_od", "dat_od"),
                                },
                            });
                            break;
                        case "slozka_mzdy":
                            fb.addField("gselectbox", Gordic.Prefabs.Select.gCisReaderPamsdrh(), {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                model: "slozka_mzdy=>slozka_mzdy,druh=druh,druh_txt<=nazev",
                                dropdown: false,
                                serverFilters: {
                                    slozka_mzdy: new Gordic.Forms.Dependency("ixs_tks", "slozka_mzdy", true),
                                },
                            });
                            break;
                        case "oduvodneni":
                        case "oduvodneni_uk":
                            fb.addField("gstringbox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                            });
                            break;
                        case "sym":
                            fb.addField("gstringbox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                                initialValue: content["stringboxValue"],
                            });
                            break;
                        case "dat_od":
                        case "dat_souhlas":
                        case "dat_vraceni":
                            fb.addField("gdatebox", {
                                name: o.field_id,
                                validators: validators,
                                tooltip: o.field_descr ?? "",
                                disabled: !o.priz_edit_bool,
                            });
                            break;
                    }
                });
                return fb;
            }
