                            const view = content.grid_vzdPlan.ggrid("getView");
                            const vzdAkce = view.getDataRows(false, "data");
                            const index = vzdAkce.indexOf(sel);
                            content.findForms("form_detailVzdAkce").findFields().gfield("option", "disabled", true);
                            //Content.dialogs.simpleForm("Detail vzdělávací akce", form_detailVzdAkce, sel, { commandBar:["cancel"] });
                            content.dialogs
