                    content.actions.act_Delete.enabled(!content.ReadOnly && jeSpravce && content.Hodnoceni.aktivita === 100);
                    content.actions.act_Generace.visible(jeSpravce);
                    content.actions.act_Generace.enabled(!content.ReadOnly);
                    content.actions.act_Print.enabled(!content.ReadOnly && content.Hodnoceni != null && content.Hodnoceni.aktivita === 100);
                    content.actions.act_Print.visible(content.Hodnoceni == null || content.Hodnoceni.ixp == null);
