                    const jePovUprFazePrvni = (content.JePrihlHtelAkt || content.IsEdit) && content.Hodnoceni.stav_hod === WebControls.StavHodnoceni.Otazky;
                    const view = content.grid_vzdPlan.ggrid("getView");
                    content.actions.act_Detail.enabled(((content.JePrihlHtelAkt || content.IsEdit) && content.grid_vzdPlan.ggrid("getSelection").length > 0) || content.grid_vzdPlan.ggrid("getSelection").length > 0);
                    content.actions.act_New.enabled(jePovUprFazePrvni);
                    content.actions.act_Import.enabled(jePovUprFazePrvni);
                    content.actions.act_Delete.enabled(jePovUprFazePrvni && view.getCount("filter") > 0);
