            function ShowGServiceGroupResponseErr(content, result, seskupit, title, okText = "Úspěšně uloženo.") {
                if (result && result.result.length > 0) {
                    let l_errText = "";
                    for (let i = 0; i < result.result.length; i++) {
                        if (result.result[i] && result.result[i].errors && result.result[i].errors.length > 0) {
                            if (l_errText)
                                l_errText += Gordic.Gin.Globals.Enums.UsedStrings.newLineHtml;
                            for (let j = 0; j < result.result[i].errors.length; j++) {
                                if (l_errText)
                                    l_errText += Gordic.Gin.Globals.Enums.UsedStrings.newLineHtml;
                                l_errText += result.result[i].errors[j].message;
                                if (!seskupit)
                                    showError(content, title, result.result[i].errors[j].message ?? "");
                            }
                        }
                    }
                    if (l_errText) {
                        if (seskupit)
                            showError(content, title, l_errText);
                    }
                    else {
                        showSucess(content, title, okText);
                    }
                }
            }
