                let retez = "";
                if (dataListdescriptor.list_order_fields) {
                    for (const key in dataListdescriptor.list_order_fields) {
                        const vzestupne = dataListdescriptor.list_order_fields[key];
                        if (retez !== "")
                            retez += ",";
                        if (!vzestupne)
                            retez += "!";
                        retez += key;
                    }
                }
                return retez;
