            function createButtonColumn(content, action, column, sirka_nadpisu) {
                return {
                    name: column.field_name,
                    caption: column.field_caption ?? "",
                    width: sirka_nadpisu,
                    customClass: "center",
                    cellTemplate: (row) => {
                        const btn = $.newDiv().gbutton({
                            params: {
                                action: content?.actions[action],
                                actionContext: { dto: row },
                            },
                        });
                        $(btn.children()[0]).css("width", "100%");
                        return btn;
                    },
                };
            }
