            function createClassicColumn(column, columns) {
                const v_char_width = 8;
                const v_coll_add = 2;
                const v_char_caption_width = 8; //9.3;
                const v_caption_add = 2;
                var v_sirka = 0;
                let v_sirka_nadpisu = 0;
                const v_maxCollChars = 100; // 50;
                const v_caption = column.field_caption || "";
                switch (column.field_base_type?.toString()) {
                    case "BOOLEAN":
                        v_sirka = 10;
                        v_sirka_nadpisu = (v_caption.length + v_caption_add) * v_char_caption_width;
                        if (v_sirka_nadpisu > v_sirka)
                            v_sirka = v_sirka_nadpisu;
                        columns.addBooleanColumn({
                            name: column.field_name || "",
                            caption: column.field_caption || "",
                            width: v_sirka,
                            fragment: "",
                            description: column.field_tooltip ?? "",
                        });
                        break;
                    case "TEXT":
                        v_sirka = column.field_max_data_size || v_maxCollChars;
                        if (v_sirka > v_maxCollChars)
                            v_sirka = v_maxCollChars;
                        if (v_sirka < 5)
                            v_sirka = 5;
                        v_sirka = (v_sirka + v_coll_add) * v_char_width;
                        v_sirka_nadpisu = ((column.field_caption || "").length + v_caption_add) * v_char_caption_width;
                        if (v_sirka_nadpisu > v_sirka)
                            v_sirka = v_sirka_nadpisu;
                        columns.addTextColumn({
                            name: column.field_name || "",
                            caption: column.field_caption || "",
                            width: v_sirka,
                            fragment: "",
                            description: column.field_tooltip ?? "",
                        });
                        break;
                    case "DATETIME":
                        //var v_sirka = 16; JKlusacek - zmněna kvůli datumu - nebylo vidět celé
                        var v_sirka = 19;
                        v_sirka = v_sirka * v_char_width;
                        v_sirka_nadpisu = (v_caption.length + v_caption_add) * v_char_caption_width;
                        if (v_sirka_nadpisu > v_sirka)
                            v_sirka = v_sirka_nadpisu;
                        columns.addDateTimeColumn({
                            name: column.field_name || "",
                            caption: column.field_caption || "",
                            width: v_sirka,
                            fragment: "",
                            description: column.field_tooltip ?? "",
                        });
                        break;
                    case "DATE":
                    case "4": //ruční přidělení DATE v ts podle enum
                        //debugger;
                        var v_sirka = 6;
                        v_sirka = v_sirka * v_char_width;
                        v_sirka_nadpisu = ((v_caption.length < 10 ? 10 : v_caption.length) + v_caption_add) * v_char_caption_width;
                        if (v_sirka_nadpisu > v_sirka)
                            v_sirka = v_sirka_nadpisu;
                        columns.addDateColumn({
                            name: column.field_name || "",
                            caption: column.field_caption || "",
                            width: v_sirka,
                            fragment: "",
                            description: column.field_tooltip ?? "",
                        });
                        break;
                    case "NUMBER":
                        var v_sirka = 5;
                        v_sirka = v_sirka * v_char_width;
                        v_sirka_nadpisu = (v_caption.length + v_caption_add) * v_char_caption_width;
                        if (v_sirka_nadpisu > v_sirka)
                            v_sirka = v_sirka_nadpisu;
                        if (v_sirka < column.field_size)
                            v_sirka = column.field_size;
                        columns.addNumberColumn({
                            name: column.field_name || "",
                            caption: column.field_caption || "",
                            width: v_sirka,
                            fragment: "",
                            description: column.field_tooltip ?? "",
                            //editor: column.
                        });
                        break;
                    case "DECIMAL":
                        var v_sirka = 15;
                        v_sirka = v_sirka * v_char_width;
                        v_sirka_nadpisu = (v_caption.length + v_caption_add) * v_char_caption_width;
                        if (v_sirka_nadpisu > v_sirka)
                            v_sirka = v_sirka_nadpisu;
                        if (v_sirka < column.field_size)
                            v_sirka = column.field_size;
                        columns.addDecimalColumn({
                            name: column.field_name || "",
                            caption: column.field_caption || "",
                            width: column.field_size || 150,
                            fragment: "",
                            description: column.field_tooltip ?? "",
                            //format: "number(N2)", //dvě desetinná místa
                        });
                        break;
                }
            }
