            //////
            /**
             * Zjištění zda-li je objekt není undefined nebo null
             * @param obj
             */
            WebControls.isEmpty = (obj) => {
                return !(typeof obj !== "undefined" && obj !== null);
            };
            /**
             * Zjištění zda-li řetězec prázdný (obsahuje pouze mezery nebo bílé znaky) je objekt není undefined nebo null
             * @param obj
             */
            WebControls.isEmptyString = (obj) => {
                return !(typeof obj === "string" && obj.trim().length !== 0);
            };
            /**
             * Vypsání objektu na konzoli. Pokud se jedná o decimal. Tak jej vypíšu na 4 místa
             * @param obj obecný objekt
             */
            WebControls.dump = (obj) => console.log(obj instanceof Decimal ? obj.toFixed(4) + " :Dec(4)" : Gordic.Per.WebControls.toString(obj));
            /**
             * Konverze obecného objektu na řetězec
             * @param obj obecný objekt
             * @param level interní proměnná určující úroveň odsazení ( neplnit, ponechat implicitní hodnotu)
             * @returns Řetězec, který má odděleny jednotlivé položky '\n'
             */
            function toString(obj, level = 0) {
                const MAX_LEVEL = 10;
                if (obj === null) {
                    return "(null)";
                }
                if (obj === undefined) {
                    return "(undefined)";
                }
                if (typeof obj === "string")
                    return obj;
                if (typeof obj === "object") {
                    const frm = obj;
                    if (typeof obj["hasClass"] === "function" && frm.hasClass("gform")) {
                        // dump formu
                        const dto = {};
                        frm.findFields().gfield("model", "collect", dto);
                        obj = dto;
                    }
                }
                //  if  (typeof(thisForm) === "object")obj.hasClass("gform")
                let dumped_text = "";
                if (!level)
                    level = 0;
                let level_padding = "";
                for (let j = 0; j < level + 1; j++)
                    level_padding += "    ";
                if (typeof obj === "object") {
                    for (const item in obj) {
                        const value = obj[item];
                        if (typeof value === "object") {
                            dumped_text += level_padding + "'" + item + "' \n";
                            if (level <= MAX_LEVEL)
                                dumped_text += Gordic.Per.WebControls.toString(value, level + 1); // LIMIT
                        }
                        else {
                            dumped_text += level_padding + "'" + item + "' => " + value + " (" + typeof value + ")" + "\n";
                        }
                    }
                }
                else {
                    dumped_text = obj + " (" + typeof obj + ")";
                }
                return dumped_text;
            }
