            function addDays(date, days) {
                const newDate = new Date(parseDate(date).getTime());
                newDate.setDate(newDate.getDate() + days);
                return newDate;
            }
            WebControls.addDays = addDays;
            /**
             * Přidá k datumu roky
             * @param date Datum
             * @param years Počet roků
             * @returns novou instanci Date
             * @author DCH
             */
            function addYears(date, years) {
                const newDate = new Date(parseDate(date).getTime());
                newDate.setFullYear(newDate.getFullYear() + years);
                return newDate;
            }
            WebControls.addYears = addYears;
            /**
             * Získá počet přestupných dnů
             * @param datum1
             * @param datum2
             * @returns
             * @author DCH
             */
            function leapMezidd(datum1, datum2) {
                let dat_od = datum1.getTime() < datum2.getTime() ? datum1 : datum2;
                let dat_do = datum1.getTime() < datum2.getTime() ? datum2 : datum1;
                dat_od = dat_od.getMonth() + 1 > 2 ? new Date(dat_od.getFullYear() + 1, 1, 1) : new Date(dat_od.getFullYear(), 1, 1);
                dat_do =
                    dat_do.getMonth() + 1 > 2 || (dat_do.getMonth() + 1 == 2 && dat_do.getDate() == 29)
                        ? new Date(dat_do.getFullYear() + 1, 1, 1)
                        : new Date(dat_do.getFullYear(), 1, 1);
                return Math.abs(((dat_od.getTime() - dat_do.getTime()) / (1000 * 3600 * 24)) % 365);
            }
            WebControls.leapMezidd = leapMezidd;
            /**
             * Nastaví počet dní a roků u celkové praxi z datumů od a do
             * @author DCH
             */
            function urceniDelkyPraxe(datumOd, datumDo) {
                let rozdilDatumu = (datumDo.getTime() - datumOd.getTime()) / (1000 * 3600 * 24) + 1;
                const prestCelkem = leapMezidd(datumOd, datumDo);
                let roky = 0;
                let dny = 0;
                if (rozdilDatumu >= 0) {
                    roky = Gordic.Pam.trunc((rozdilDatumu - prestCelkem) / 365);
                    dny = rozdilDatumu - prestCelkem - 365 * roky;
                }
                else {
                    rozdilDatumu = -rozdilDatumu;
                    roky = Gordic.Pam.trunc((rozdilDatumu + prestCelkem) / 365);
                    dny = rozdilDatumu + prestCelkem - 365 * roky;
                    roky = -roky;
                    dny = -dny;
                }
                return { roky: roky, dny: dny };
            }
            WebControls.urceniDelkyPraxe = urceniDelkyPraxe;
            /**
             * Nastaví počet dní a roků u celkové praxi z datumů od a do
             * @author DCH
             */
            function urceniDelkyPraxeKoef(datumOd, datumDo, koef) {
                let rozdilDatumu = koef.times((datumDo.getTime() - datumOd.getTime()) / (1000 * 3600 * 24) + 1);
                const prestCelkem = koef.times(leapMezidd(datumOd, datumDo));
                let roky = 0;
                let dny = 0;
                if (rozdilDatumu.greaterThanOrEqualTo(0)) {
                    roky = rozdilDatumu.minus(prestCelkem).div(365).trunc().toNumber();
                    dny = rozdilDatumu
                        .minus(prestCelkem)
                        .minus(365 * roky)
                        .ceil()
                        .toNumber();
                }
                else {
                    rozdilDatumu = rozdilDatumu.negated();
                    roky = rozdilDatumu.plus(prestCelkem).div(365).trunc().toNumber();
                    dny = rozdilDatumu
                        .plus(prestCelkem)
                        .minus(365 * roky)
                        .ceil()
                        .toNumber();
                    roky = -roky;
                    dny = -dny;
                }
                while (dny >= 365) {
                    roky = roky + 1;
                    dny = dny - 365;
                }
                return { roky: roky, dny: dny };
            }
            WebControls.urceniDelkyPraxeKoef = urceniDelkyPraxeKoef;
