            /**
             * Porovnává datumy podle UTC (bez časového pásma)
             * @param date1
             * @param date2
             * @param operation Jak se má porovnávat
             * @param onlyDate Jestli porovnávat jen datum bez času
             * @author DCH
             */
            function compareDates(date1, date2, operation, onlyDate = false) {
                if (date1 == null || date2 == null)
                    return false;
                // Funkce pro převod na UTC (pouze datum nebo datum+čas)
                const toUTC = (date, onlyDate) => {
                    if (onlyDate) {
                        // Převod pouze na datum (ignoruje čas)
                        return new Date(date.getFullYear(), date.getMonth(), date.getDate());
                    }
                    // Převod na UTC datum a čas
                    return new Date(date.getTime() - date.getTimezoneOffset() * 60000);
                };
                // Převést oba datumy na UTC
                const utcDate1 = toUTC(parseDate(date1), onlyDate);
                const utcDate2 = toUTC(parseDate(date2), onlyDate);
                // Získat časové hodnoty v milisekundách
                const value1 = utcDate1.getTime();
                const value2 = utcDate2.getTime();
                //// Získání hodnot dat v UTC (ignorujeme časová pásma)
                //const value1 = onlyDate
                //    ? Date.UTC(parseDate(date1).getUTCFullYear(), parseDate(date1).getUTCMonth(), parseDate(date1).getUTCDate())
                //    : Date.UTC(
                //          parseDate(date1).getUTCFullYear(),
                //          parseDate(date1).getUTCMonth(),
                //          parseDate(date1).getUTCDate(),
                //          parseDate(date1).getUTCHours(),
                //          parseDate(date1).getUTCMinutes(),
                //          parseDate(date1).getUTCSeconds()
                //      );
                //const value2 = onlyDate
                //    ? Date.UTC(parseDate(date2).getUTCFullYear(), parseDate(date2).getUTCMonth(), parseDate(date2).getUTCDate())
                //    : Date.UTC(
                //          parseDate(date2).getUTCFullYear(),
                //          parseDate(date2).getUTCMonth(),
                //          parseDate(date2).getUTCDate(),
                //          parseDate(date2).getUTCHours(),
                //          parseDate(date2).getUTCMinutes(),
                //          parseDate(date2).getUTCSeconds()
                //      );
                // Porovnání na základě zadané operace
                switch (operation) {
                    case WebControls.DateCompareOperation.Equal:
                        return value1 === value2;
                    case WebControls.DateCompareOperation.Greater:
                        return value1 > value2;
                    case WebControls.DateCompareOperation.GreaterOrEqual:
                        return value1 >= value2;
                    case WebControls.DateCompareOperation.Less:
                        return value1 < value2;
                    case WebControls.DateCompareOperation.LessOrEqual:
                        return value1 <= value2;
                    default:
                        throw new Error(`Neznámá operace: ${operation}`);
                }
            }
            WebControls.compareDates = compareDates;
            /**
             * Zjišťuje, zda je daný rok přestupný.
             * @param year Testovaný rok
             * @author DCH
             */
            function isLeapYear(year) {
                return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
            }
