            function createFilterForm(descriptionMasky) {
                let vysledek = new Array;
                descriptionMasky.forEach(item => {
                    let form = new Gordic.Forms.Form({ tabLabel: item.detail_caption ?? "", layoutDescriptor: "L4M4S2, L-3-8-1, M-12-11-1, S-12-11-1, breaks-700-1000", opened: false });
                    item.detail_fields?.forEach(field => {
                        var v_field_name = field.field_name ?? "";
                        var v_field_caption = field.field_caption ?? "";
                        var v_field_base_type = field.field_base_type || "OTHER";
                        var v_tooltip = field.field_tooltip ?? undefined;
                        var v_validators;
                        v_validators = new Array();
                        //debugger;
                        form.addRow({ label: v_field_caption, name: v_field_name });
                        if (field.field_name_source) {
                            let columns = field.field_name_source.split(".");
                            let ciselnik = columns[0];
                            let sloupec = v_field_name;
                            if (columns.length > 0)
                                sloupec = columns[1];
                            switch (ciselnik) {
                                case "gCisReaderCasCiselnik":
                                    form.addField("gselectbox", Gordic.Prefabs.Select.gCisReaderCasCiselnik(), {
                                        //name: field.field_name ?? "",
                                        dropdown: false,
                                        model: "model." + v_field_name + "=value.ixs_hci",
                                        serverFilters: {
                                            ciselnik_sloupec: sloupec,
                                            dat_od: { o: "<=", v: Per.WebControls.DateToJSONFormatstring(new Date()) },
                                            dat_do: { o: ">=", v: Per.WebControls.DateToJSONFormatstring(new Date()) },
                                            aktivita: 100
                                        },
                                        validators: v_validators,
                                        tooltip: v_tooltip
                                    });
                                    break;
                                default:
                                    form.addField("gselectbox", eval("Gordic.Prefabs.Select." + ciselnik + "()"), {
                                        //name: field.field_name ?? "",
                                        dropdown: false,
                                        model: "model." + v_field_name + "=value." + sloupec,
                                        //serverFilters: {
                                        //    ciselnik_sloupec: sloupec,
                                        //    dat_od: { o: "<=", v: Per.WebControls.DateToJSONFormatstring(new Date()) },
                                        //    dat_do: { o: ">=", v: Per.WebControls.DateToJSONFormatstring(new Date()) },
                                        //    aktivita: 100
                                        //},
                                        validators: v_validators,
                                        tooltip: v_tooltip
                                    });
                                    break;
                            }
                        }
                        else {
                            switch (v_field_base_type) {
                                case "TEXT":
                                    if (field.field_size !== undefined && field !== null)
                                        v_validators.push(new Gordic.Validators.Length({ params: { min: 0, max: field.field_size } }));
                                    var fieldOptions = {
                                        //name: field.field_name ?? "",
                                        //disabled: v_readonly,
                                        validators: v_validators,
                                        emptyValue: "",
                                        tooltip: v_tooltip
                                    };
                                    form.addField("gstringbox", fieldOptions, Gordic.Prefabs.String.withOperators());
                                    break;
                                case "DATETIME":
                                    form.addField("gdatebox", {
                                        //name: field.field_name ?? "",
                                        //disabled: v_readonly,
                                        validators: v_validators,
                                        valueType: "datetime",
                                        tooltip: v_tooltip
                                    }, Gordic.Prefabs.Date.withOperators());
                                    break;
                                case "DATE":
                                    form.addField("gdatebox", "w-6", {
                                        name: v_field_name + "Start",
                                        model: v_field_name + ".start=value",
                                        tooltip: "Min",
                                        emptyValue: null,
                                        defaultValue: null
                                    });
                                    form.addField("gdatebox", "w-6", {
                                        name: v_field_name + "End",
                                        model: v_field_name + ".end=value",
                                        tooltip: "Max",
                                        emptyValue: null,
                                        defaultValue: null
                                    });
                                    break;
                                case "NUMBER":
                                    var numFieldOptions = {
                                        //name: field.field_name ?? "",
                                        //disabled: v_readonly,
                                        validators: v_validators,
                                        tooltip: v_tooltip
                                    };
                                    form.addField("gnumberbox", numFieldOptions, Gordic.Prefabs.Number.withOperators());
                                    break;
                                case "DECIMAL":
                                    form.addField("gstringbox", {
                                        //name: field.field_name ?? "",
                                        //disabled: v_readonly,
                                        validators: v_validators,
                                        tooltip: v_tooltip
                                    });
                                    break;
                                case "BOOLEAN":
                                    form.addField("gcheck", {
                                        //name: field.field_name ?? "",
                                        //disabled: v_readonly,
                                        validators: v_validators,
                                        tooltip: v_tooltip
                                    });
                                    break;
                            }
                        }
                    });
                    //                .addSection("jres:31302167") //RC 31302167 : Datum podání
                    //.addRow("Od - Do")
                    //.addField("gintervalbox", { name: "dat_vyst" })
                    //.addSection("Adresa")
                    //.addRow("Ulice")
                    //.addField("gstringbox", { name: "esu_cs_ulice" })
                    vysledek.push(form);
                });
                //const myList = [1, 2, 3, 4, 5]
                //myList.forEach(item => {
                //    console.log(item)
                //})
                return vysledek;
            }
            WebControls.createFilterForm = createFilterForm;
            function createFilterOsoby() {
                return new Gordic.Forms.Form({
                    tabLabel: "Osoby",
                    layoutDescriptor: "L4M4S2, L-3-8-1, M-12-11-1, S-12-11-1, breaks-700-1000"
                })
                    .addText("Fulltext control");
            }
            WebControls.createFilterOsoby = createFilterOsoby;
