                                IxsEsu: content.IxsEsu,
                                IsEditable: content.IsEditable,
                                IsNewRecord: content.IsNewRecord,
                                PageId: "detail_persvpo_vyneti_tab",
                                IxsPpv: content.Detail.detail?.ixs_ppv,
                                Poradi: content.Detail.detail?.poradi_vpo,
