                    form_detail = Gordic.Per.WebControls.createFormDetail(form_detail, content.Detail.metaData?.detail_fields ?? []);
                    const form = $.newDiv().appendTo(content.element).gform("createFrom", form_detail);
                    const radioField = form.findFields("radio_ozn_pov");
                    if (radioField.length > 0) {
                        radioField.gfield("option", "change", (ev, obj) => {
                            const form = $(ev.target).closest(".gform");
                            content.setVisibility(form, obj.value);
                        });
                    }
                    form.gform("complete");
                    form.findFields().gfield("model", "apply", content.Detail.detail, { initialValues: true });
                    content.setVisibility(form, content.Detail.detail?.radio_ozn_pov);
