                            actDeleteZapocty: {
                                caption: "jres:29120051",
                                icon: "gi-bin",
                                enabled: content.IsEditable,
                                run: function () {
                                    const sel = content.gridZapoctyPraxe.ggrid("getSelection")[0];
                                    const guid = Gordic.Utils.generateGuid();
                                    content.beginOperation({ id: guid });
                                    content.isl.OsoPPV.listDokladyPlvPam({ filters: { ixs_ppv: content.Detail.detailPPV.ixs_ppv } })
                                        .getData()
                                        .then((data) => {
                                        let jeZapocetVDokladech = false;
                                        if (data.length > 0 && sel.dat_zap_praxe) {
                                            for (let i = 0; i < data.length; i++) {
                                                const dto = data[i];
                                                if (dto.dat_zap_praxe && parseDate(dto.dat_zap_praxe).getTime() == parseDate(sel.datum_zapocet).getTime()) {
                                                    jeZapocetVDokladech = true;
                                                    break;
                                                }
                                            }
                                        }
                                        if (!content.ParametrPerPovMazatSchvalZap && jeZapocetVDokladech) {
                                            content.dialogs.warning("Informace", "Zápočet praxe s datem zápočtu {0} nelze odstranit, protože je již použit v dokladech mezd PAM!");
                                        }
                                        content.dialogs.confirm("Zrušení zápočtu praxe osoby", "Přejete si vymazat zápočet praxe osoby?").on("yes", () => {
                                            const guid = Gordic.Utils.generateGuid();
                                            content.beginOperation({ id: guid });
                                            content.isl.PpvZapoctyPraxe.delete(sel)
                                                .getData()
                                                .then(() => {
                                                WebControls.showSucess(content, "Zrušení zápočtu praxe osoby", "Zrušeno.");
                                            })
                                                .catch((err) => {
                                                if (err.errorType === "info") {
                                                    //"info" = C# GNonFatalException
                                                    WebControls.showError(content, "Zrušení zápočtu praxe osoby", (err.title ? err.title + " - " : "") + err.message);
                                                }
                                                else
                                                    throw err;
                                            })
                                                .always(() => content.endOperation(guid));
                                        });
                                    })
                                        .always(() => content.endOperation(guid));
                                },
                            },
