                                    content.dialogs
                                        .showWindow("Gordic.Per.WebControls.GDetailPlatVymer", {
                                        IxsEsu: content.IxsEsu,
                                        Id: "detail_persplv_tab",
                                        IsEditable: content.IsEditable,
                                        IsNewRecord: false,
                                        IxsPpv: sel.ixs_ppv,
                                        Poradi: sel.poradi_plv,
                                        JeSluzba: content.jeSluzba,
                                        DatDoPpv: content.findFields("PPV_do").gfield("getValue"),
                                        ZmenyPpvList: content.Detail.detail?.ZmenyPPV,
                                        ZarazeniSMList: content.Detail.detail?.PracovniZarazeni,
                                        DruhPpv: content.findFields("ixs_hci_drpp").gfield("getValue")?.id,
                                    }, { width: 730, height: 530 })
