            //#region ts verze CanEdit na DTO
            /** Typesciptová verze CanEdit na DTO */
            function CanEditZSZ(dto, vlastnost) {
                if (dto.read_only || ![0, 10].includes(dto.stav_odeslani))
                    return false;
                if (vlastnost === "preloz_kod_urad" && dto.druh_zmeny == "3A" && dto.duvod_zmeny == "20")
                    return true;
                if (["pusob_stat", "pusob_region", "pusob_kod_obec", "pusob_zahr_obec"].includes(vlastnost) &&
                    (["1H", "1I", "R1", "R2", "R3", "R4", "R5"].includes(dto.druh_zmeny) ||
                        ["2A", "3B", "3D", "3E", "3F", "3G", "3J", "3K", "4E", "4F"].includes(dto.druh_zmeny) ||
                        (dto.druh_zmeny == "3A" && ["10", "20", "40"].includes(dto.duvod_zmeny))))
                    return true;
                return false;
            }
            WebControls.CanEditZSZ = CanEditZSZ;
