var Gordic;
(function (Gordic) {
    var Per;
    (function (Per) {
        var WebControls;
        (function (WebControls) {
            /**PEV - Zda je požadavek splněn*/
            function jePozadavekSplnen(pozadavek) {
                if (pozadavek == null)
                    return false;
                if (pozadavek === "0000BHR08Z1F" || pozadavek === "0000BHR08Z2A" || pozadavek === "0000BHR08Z35")
                    return true;
                else
                    return false;
            }
            WebControls.jePozadavekSplnen = jePozadavekSplnen;
            /**
             * PEV - Získání DTO plánu k danému datu
             * @param cnt Aktuální content
             * @param upozornitZadnyPlan Zda upozornit na neexistující plán
             * @param dotazVicePlanu Zda vybírat plán, pokud je jich více
             * @param plany Seznam DTO
             * @param datum Datum k upřesnění plánu (nepovinný argument -> aktuální datum)
             * @returns Promise s DTO
             */
            function getPlanOsoDto(cnt, upozornitZadnyPlan, dotazVicePlanu, plany, datum = new Date()) {
                const def = $.Deferred();
                //debugger
                if (plany != null && plany.length > 0) {
                    //kontrola na aktuálnost
                    const aktPlany = plany.filter((r) => (r.dat_od == null ? datum.setHours(0, 0, 0, 0) : new Date(r.dat_od.toString()).setHours(0, 0, 0, 0)) <= datum.setHours(0, 0, 0, 0) &&
                        (r.dat_do == null ? datum.setHours(0, 0, 0, 0) : new Date(r.dat_do.toString()).setHours(0, 0, 0, 0)) >= datum.setHours(0, 0, 0, 0));
                    if (aktPlany.length == 0) {
                        if (upozornitZadnyPlan) {
                            cnt.dialogs.warning("jres:29120102", "jres:34900259"); //RC 29120285 : Neexistuje žádný aktuálně platný vzdělávací plán.
                        }
                        def.resolve(null);
                    }
                    else if (aktPlany.length == 1) {
                        def.resolve(aktPlany[0]);
                    } //end if
                    else {
                        if (dotazVicePlanu) {
                            cnt.dialogs
                                .showModalWindow("Gordic.Pev.WebClient.GVyberPlanuZam", { Plany: aktPlany }, { with: 600, height: 600 })
                                .on("close", (ev, returnVal) => {
                                if (returnVal != null) {
                                    def.resolve(returnVal);
                                }
                            });
                        }
                        else {
                            aktPlany.sort((a, b) => parseDate(b.dat_od).getTime() - parseDate(a.dat_od).getTime());
                            def.resolve(aktPlany[0]);
                        }
                    }
                }
                else if (upozornitZadnyPlan) {
                    cnt.dialogs.warning("jres:29120102", "jres:34900124");
                    def.resolve(null);
                }
                else
                    def.resolve(null);
                return def.promise();
            }
            /**
             * PEV - Získání identifikátoru plánu k danému datu
             * @param cnt Aktuální content
             * @param plany Seznam plánů
             * @param ixs_esu Identifikátor osoby
             * @param upozornitZadnyPlan Zda upozornit na neexistující plán
             * @param dotazVicePlanu Zda vybírat z více plánů
             * @param vytvoritNovy Zda vytvořit nový plán v případě, že neexistuje
             * @param datum Datum k upřesnění plánu (nepovinný agrument -> aktuální datum)
             * @returns
             */
            function getIxsPlv(cnt, plany, ixs_esu, upozornitZadnyPlan, dotazVicePlanu, vytvoritNovy, datum = new Date()) {
                const def = $.Deferred();
                getPlanOsoDto(cnt, upozornitZadnyPlan, dotazVicePlanu, plany, datum).then((dto) => {
                    if (dto == null || dto.ixs_plv == null) {
                        if (vytvoritNovy) {
                            const minDate = new Date(1900, 0, 1);
                            const maxDate = new Date(2999, 11, 31);
                            const novyPlan = {
                                nazev: "Vzdělávací plán ({0} - {1})".format(minDate.toLocaleDateString("cs"), maxDate.toLocaleDateString("cs")),
                                dat_od: minDate,
                                dat_do: maxDate,
                            };
                            const guid_novyPlan = Gordic.Utils.generateGuid();
                            cnt.beginOperation({ id: guid_novyPlan, text: "jres:34900423" }); //RC 34900423 : Vytvářím nový plán
                            cnt.isl.PevVzdelavaciPlany.savePlanSVazbou({ rq: { data: novyPlan }, ixs_esu: ixs_esu, dat_od: minDate, dat_do: maxDate })
                                .getData()
                                .done((result) => {
                                if (result != null) {
                                    def.resolve(result.ixs_plv);
                                }
                            })
                                .fail((xhr, type, vobj) => {
                                if (type === "exception") {
                                    if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                        vobj.handled = true;
                                        //cnt.showFlash(vobj.baseMessage, "error");
                                        Per.WebControls.showError(cnt, "jres:34900423", vobj.baseMessage); //RC 34900423 : Vytvářím nový plán
                                        def.reject();
                                    }
                                }
                            })
                                .always(() => {
                                cnt.endOperation(guid_novyPlan);
                            });
                        }
                        else
                            def.resolve(null);
                    }
                    else {
                        def.resolve(dto.ixs_plv);
                    }
                });
                return def.promise();
            }
            WebControls.getIxsPlv = getIxsPlv;
            /**
             * PEV - založení nového plánu osoby
             * @param cnt
             * @param ixs_esu
             */
            function createPlanOso(cnt, ixs_esu) {
                if (ixs_esu == null)
                    return;
                const def = $.Deferred();
                const plan = {
                    nazev: "Vzdělávací plán (" + new Date(1900, 0, 1).toLocaleDateString("cs") + " - " + new Date(2999, 11, 31).toLocaleDateString("cs") + ")",
                    dat_od: new Date(1900, 0, 1),
                    dat_do: new Date(2999, 11, 31),
                };
                const guid = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid, text: "jres:34900413" }); //RC 34900413 : Probíhá uložení nového plánu
                cnt.isl.PevVzdelavaciPlany.savePlanSVazbou({ rq: { data: plan }, ixs_esu: ixs_esu, dat_od: new Date(1900, 0, 1), dat_do: new Date(2999, 11, 31) })
                    .getData()
                    .done((result) => {
                    def.resolve(result.ixs_plv);
                })
                    .fail((xhr, type, vobj) => {
                    if (type === "exception") {
                        if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                            vobj.handled = true;
                            //cnt.showFlash(vobj.baseMessage, "error");
                            Per.WebControls.showError(cnt, "jres:34900414", vobj.baseMessage); //RC 34900414 : Uložení nového plánu
                        }
                    }
                })
                    .always(() => {
                    cnt.endOperation(guid);
                });
                return def.promise();
            }
            /**
             * PEV - Zjistí nově přidané osoby k turnusu pro odeslání pozvánky
             * @param cnt Content
             * @param ixs_kur Identifikátor turnusu
             * @param poradi Pořadí turnusu
             * @param osoby Seznam přiřazených osob
             */
            function getNewOsoTur(cnt, ixs_kur, poradi, list_oso) {
                const def = $.Deferred();
                const osoby = [];
                if (ixs_kur == null || poradi == null || list_oso.length === 0)
                    return def.resolve(osoby);
                const guid = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid, text: "Načítám osoby" });
                cnt.isl.PevVzdelavaciKurzy.listOsoKurz({ filters: { ixs_kur: ixs_kur, poradi_kur: poradi, aktivni: true } })
                    .getData()
                    .done((result) => {
                    list_oso.forEach((osoba) => {
                        if (result.filter((r) => r.ixs_esu === osoba.ixs_esu).length === 0) {
                            osoby.push(osoba.ixs_esu);
                        }
                    });
                    def.resolve(osoby);
                })
                    .always(() => {
                    cnt.endOperation(guid);
                });
                return def.promise();
            }
            WebControls.getNewOsoTur = getNewOsoTur;
            /**
             * PEV - Odešle pozvánky osobám na kurz
             * @param cnt Content
             * @param turnus DTO turnusu
             * @param osoby Seznam identifikátorů osob
             */
            function sendInvitation(cnt, turnus, osoby) {
                if (turnus == null || turnus.nazev_kurz == null || osoby.length === 0)
                    return;
                const srv = cnt.createServiceContent("Gordic.Pev.WebClient.GPevFunctions");
                const guid = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid, text: "jres:34900723" }); //RC 34900723 : Posílání e-mailu
                osoby.forEach((osoba) => {
                    const guid_adr = Gordic.Utils.generateGuid();
                    cnt.beginOperation({ id: guid_adr, text: "jres:34900724" }); //RC 34900724 : Načítám e-mailovou adresu osoby
                    cnt.isl.OsoKontaktUdaje.list({ filters: { ixs_esu: osoba, dat_od: new Date(), aktivita: true } })
                        .getData()
                        .done((result) => {
                        let email = "";
                        for (let i = 0; i < result.length; i++) {
                            if (result[i].mail != null) {
                                email = result[i].mail;
                                break;
                            }
                        }
                        if (email !== "") {
                            srv.call("SendMailWithTemplate", { adresa: email, turnus: turnus });
                        }
                    })
                        .always(() => {
                        cnt.endOperation(guid_adr);
                    });
                });
            }
            WebControls.sendInvitation = sendInvitation;
            /**PEV - Zrušení zařazení osoby na turnus */
            function deleteOso(cnt, ixs_kur, poradi, ixs_esu, stav_abs) {
                if (ixs_kur == null || poradi == null || ixs_esu == null || stav_abs == null) {
                    return;
                }
                if (stav_abs !== 0 && !(cnt["DebugMode"] || cnt["ParametrPevRadPovMaz"])) {
                    cnt.dialogs.warning("jres:34900085", "jres:34900401"); //RC 34900401 : Osoba má již určeno absolvování kurzu! Zařazení již nejde zrušit.
                    return;
                }
                else {
                    cnt.dialogs
                        .confirm("jres:34900085", stav_abs !== 0 ? "jres:34900402" : "jres:34900403") //RC 34900403 : Přejete si opravdu odstranit zařazení osoby na tento turnus?
                        .on("yes", () => {
                        const guid = Gordic.Utils.generateGuid();
                        cnt.beginOperation({ id: guid, text: "jres:34900404" }); //RC 34900404 : Probíhá odstranění zařazení do kurzu
                        cnt.isl.PevVzdelavaciKurzy.cancelUcastnikaTurnusu({
                            rq: { data: { ixs_esu: ixs_esu, ixs_kur: ixs_kur, poradi: poradi, stav_abs: stav_abs } },
                            zmenitNakl: false,
                        })
                            .getData()
                            .done(() => {
                            //cnt.showFlash("Odstraněno.", "success");
                            Per.WebControls.showSucess(cnt, "jres:34900085", "jres:34900086"); //RC 34900085 : Odstranění zařazení do kurzu
                            cnt.actions.act_LoadOso.run();
                        })
                            .fail((xhr, type, vobj) => {
                            if (type === "exception") {
                                if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                    vobj.handled = true;
                                    //cnt.showFlash(vobj.baseMessage, "error");
                                    Per.WebControls.showError(cnt, "jres:34900085", vobj.baseMessage); //RC 34900085 : Odstranění zařazení do kurzu
                                }
                            }
                        })
                            .always(() => {
                            cnt.endOperation(guid);
                        });
                    });
                }
            }
            WebControls.deleteOso = deleteOso;
            //#region Absolvování
            function absolvovaniKurzuDetailx(cnt, osoba, turnus, uspesni, neuspesni, neucast) {
                if (turnus == null)
                    return;
                let castkaOso; // = new Decimal(0);
                let pocetDnuSkoleni; // = new Decimal(0);
                if (turnus.stav_abs === 0 || osoba == null) {
                    //není uloženo nebo nevím osobu
                    if (turnus.c_jed == null || parseDecimal(turnus.c_jed ?? 0).eq(0)) {
                        if (turnus.c_celk == null)
                            castkaOso = new Decimal(0);
                        else {
                            if (turnus.pocet_osob == null || turnus.pocet_osob === 0)
                                castkaOso = parseDecimal(turnus.c_celk ?? 0);
                            else
                                castkaOso = parseDecimal(turnus.c_celk ?? 0).div(turnus.pocet_osob);
                        }
                    }
                    else
                        castkaOso = parseDecimal(turnus.c_jed ?? 0);
                    pocetDnuSkoleni = parseDecimal(turnus.rozsah_dny ?? 0).plus(turnus.rozsah_hod == null ? 0 : parseDecimal(turnus.rozsah_hod).div(8));
                }
                else {
                    castkaOso = parseDecimal(turnus.c_nakl_uc ?? 0);
                    pocetDnuSkoleni = parseDecimal(turnus.poc_dnu_vzdel ?? 0);
                }
                cnt.navigate(/*dialogs.showModalWindow*/ "Gordic.Pev.WebClient.GAbsolvovaniKurzu", {
                    IxsEsu: osoba?.ixs_esu,
                    NazevEsu: osoba?.nazev,
                    IxsKur: turnus.ixs_kur,
                    PoradiKur: turnus.poradi,
                    StavAbs: turnus.stav_abs,
                    CNaklUc: castkaOso,
                    PocDnuVzdel: pocetDnuSkoleni,
                    DatZk: turnus.dat_zk,
                    DatPlatZk: turnus.dat_plat_zk,
                    DokladNazev: turnus.doklad_nazev,
                    DokladCislo: turnus.doklad_cislo,
                    DokladVydal: turnus.doklad_vydal,
                    DateDoklad: turnus.date_doklad,
                    DatZavazekDo: turnus.dat_zavazek_do,
                    CZavazek: osoba == null || osoba.ixs_esu == null ? castkaOso : turnus.c_zavazek,
                    Poznamka: turnus.poznamka_zar,
                    AbsReadOnly: osoba == null || osoba.ixs_esu == null,
                }).on("close", (ev, ret) => {
                    if ("StavAbs" in ret &&
                        "CNaklUc" in ret &&
                        "PocDnuVzdel" in ret &&
                        "DatZk" in ret &&
                        "DatPlatZk" in ret &&
                        "DokladCislo" in ret &&
                        "DokladNazev" in ret &&
                        "DokladVydal" in ret &&
                        "DateDoklad" in ret &&
                        "DatZavazekDo" in ret &&
                        "CZavazek" in ret) {
                        //uložené data
                        const novyTurnus = { ...turnus };
                        const predchoziStavAbs = turnus.stav_abs;
                        novyTurnus.stav_abs = ret.StavAbs;
                        novyTurnus.poc_dnu_vzdel = ret.PocDnuVzdel;
                        novyTurnus.c_nakl_uc = ret.CNaklUc;
                        novyTurnus.dat_zk = ret.DatZk;
                        novyTurnus.dat_plat_zk = ret.DatPlatZk;
                        novyTurnus.doklad_cislo = ret.DokladCislo;
                        novyTurnus.date_doklad = ret.DatumDoklad;
                        novyTurnus.doklad_vydal = ret.DokladVydal;
                        novyTurnus.doklad_nazev = ret.DokladNazev;
                        novyTurnus.poznamka_zar = ret.Poznamka;
                        novyTurnus.dat_zavazek_do = ret.DatZavazekDo;
                        novyTurnus.c_zavazek = ret.CZavazek;
                        novyTurnus.poc_hodin_pam = parseDecimal(ret.PocDnuVzdel).times(8).truncated().toNumber();
                        novyTurnus.c_mzd_nakl = ret.CNaklUc;
                        if (osoba != null && osoba.ixs_esu != null) {
                            absolvovaniKurzu(cnt, osoba.ixs_esu, osoba.nazev, novyTurnus, predchoziStavAbs, ret.JeZmenaPozadavku);
                        }
                        else {
                            absolvovaniKurzuViceOsob(cnt, novyTurnus, uspesni, neuspesni, neucast, ret.JeZmenaPozadavku);
                        }
                    }
                    else {
                        //trigger event plnění požadavku
                        if (ret.JeZmenaPozadavku)
                            cnt.element.trigger("PlneniPozadavku");
                    }
                });
            }
            function absolvovaniKurzuViceOsob(cnt, turnus, uspesni, neuspesni, neucast, aktualizovatVzdy) {
                if (turnus == null || ((uspesni == null || uspesni.length === 0) && (neuspesni == null || neuspesni.length === 0) && (neucast == null || neucast.length === 0))) {
                    if (aktualizovatVzdy)
                        cnt.element.trigger("AbsolvovaniTurnusu");
                    return;
                }
                const osoby = [];
                const guid_poz = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid_poz, text: "jres:34900409" }); //RC 34900409 : Načítám požadavky kurzu
                cnt.isl.PevVzdelavaciKurzy.listPozadavkyKurz({ filters: { ixs_kur: turnus.ixs_kur, aktivni: true } })
                    .getData()
                    .done((pozadavkyKurz) => {
                    const zrusenoUzivatelem = false;
                    //ÚSPĚŠNÍ
                    absolvovaniKurzuViceOsobNapln(cnt, turnus, uspesni, 10, pozadavkyKurz).then((ret_osoby_uspesni) => {
                        ret_osoby_uspesni.forEach((item) => {
                            osoby.push(item);
                        });
                        //NEÚSPĚŠNÍ
                        turnus.dat_plat_zk = null;
                        turnus.doklad_cislo = null;
                        turnus.date_doklad = null;
                        turnus.doklad_vydal = null;
                        turnus.doklad_nazev = null;
                        absolvovaniKurzuViceOsobNapln(cnt, turnus, neuspesni, 20, pozadavkyKurz).then((ret_osoby_neuspesni) => {
                            ret_osoby_neuspesni.forEach((item) => {
                                osoby.push(item);
                            });
                            //NEÚČAST
                            turnus.dat_zk = null;
                            absolvovaniKurzuViceOsobNapln(cnt, turnus, neucast, 30, pozadavkyKurz).then((ret_osoby_neucast) => {
                                ret_osoby_neucast.forEach((item) => {
                                    osoby.push(item);
                                });
                                //ULOŽENÍ
                                if (osoby.length > 0) {
                                    const promises = [];
                                    const guid_save = Gordic.Utils.generateGuid();
                                    cnt.beginOperation({ id: guid_save, text: "jres:34900411" }); //RC 34900411 : Probíhá uložení plnění
                                    osoby.forEach((item) => {
                                        const poz = [];
                                        const pozPlan = [];
                                        item.pozadavky.forEach((item) => {
                                            poz.push(item.poz);
                                            pozPlan.push(item.pozPlan);
                                        });
                                        const dto = {
                                            turnus: item.turnusOso,
                                            pozadavky: poz,
                                            pozadavkyPlan: pozPlan,
                                            jenPozadavky: false,
                                        };
                                        promises.push(cnt.isl.PevOsoba.savePlneniPlanuUcastOso(dto)
                                            .getData()
                                            .done(() => {
                                            //
                                        })
                                            .fail((xhr, type, vobj) => {
                                            if (type === "exception") {
                                                if (vobj.baseType === "Gordic.General.GNonFatalException" ||
                                                    vobj.baseType === "Gordic.General.GArgumentNullException") {
                                                    vobj.handled = true;
                                                    //cnt.showFlash(vobj.baseMessage, "error");
                                                    Per.WebControls.showError(cnt, "jres:34900412", vobj.baseMessage); //RC 34900412 : Uložení plnění plánu
                                                }
                                            }
                                        }));
                                    });
                                    //čekání na proběhnutí posledního savu, pak spustím načtení dat
                                    $.when
                                        .apply(promises)
                                        .then(() => {
                                        cnt.element.trigger("AbsolvovaniTurnusu");
                                    })
                                        .always(() => {
                                        cnt.endOperation(guid_save);
                                    });
                                }
                                else if (aktualizovatVzdy) {
                                    cnt.element.trigger("AbsolvovaniTurnusu");
                                }
                            }, () => {
                                //rejected
                                if (aktualizovatVzdy)
                                    cnt.element.trigger("AbsolvovaniTurnusu");
                            });
                        }, () => {
                            //rejected
                            if (aktualizovatVzdy)
                                cnt.element.trigger("AbsolvovaniTurnusu");
                        });
                    }, () => {
                        //rejected
                        if (aktualizovatVzdy)
                            cnt.element.trigger("AbsolvovaniTurnusu");
                    });
                })
                    .always(() => {
                    cnt.endOperation(guid_poz);
                });
            }
            /**
             * Mezikrok uložení absolvování, naplnění seznamu údajů pro uložení
             * @param cnt Content
             * @param turnus Turnus
             * @param ucastnici Seznam účastníků
             * @param stav_abs Stav absolvování
             * @param pozadavkyKurz Seznam požadavků kurzu
             * @returns Seznam turnusů osob a jejich požadavků
             */
            async function absolvovaniKurzuViceOsobNapln(cnt, turnus, ucastnici, stav_abs, pozadavkyKurz) {
                const def = $.Deferred();
                const osoby = [];
                if (turnus == null || ucastnici == null || ucastnici.length === 0 || stav_abs == null || pozadavkyKurz == null) {
                    def.resolve(osoby);
                    return def.promise();
                }
                let jeZruseno = false;
                for (const item of ucastnici) {
                    const novyTurnus = Gordic.Utils.DeepClone(turnus);
                    novyTurnus.stav_abs = stav_abs;
                    novyTurnus.ixs_esu = item.ixs_esu;
                    novyTurnus.dat_prihl = item.dat_prihl;
                    await absolvovaniKurzuDoplneni(cnt, item.ixs_esu, item.nazev, novyTurnus, pozadavkyKurz, item.stav_abs, cnt.globalSettings?.get("Global.Pev.AppSettings.PovoleniKontrolaPropojeni") ?? false).then((pozadavky) => {
                        if (pozadavky != null) {
                            osoby.push({ turnusOso: novyTurnus, pozadavky: pozadavky });
                        }
                        else {
                            jeZruseno = true;
                        }
                    });
                    if (jeZruseno) {
                        def.reject();
                        break;
                    }
                }
                def.resolve(osoby);
                return def.promise();
            }
            /**
             * Absolvování kurzu
             * @param cnt Content
             * @param ixs_esu_osoba Identifikátor osoby
             * @param nazev_osoba Název osoby
             * @param turnus DTO turnusu
             * @param predchoziStavAbs Předchozí stav absolvování
             * @param aktualizovatVzdy Zda aktualizovat i při zrušení
             */
            function absolvovaniKurzu(cnt, ixs_esu_osoba, nazev_osoba, turnus, predchoziStavAbs, aktualizovatVzdy) {
                if (turnus == null || ixs_esu_osoba == null || nazev_osoba == null) {
                    if (aktualizovatVzdy)
                        cnt.element.trigger("AbsolvovaniTurnusu");
                    return;
                }
                const guid = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid, text: "jres:34900409" }); //RC 34900409 : Načítám požadavky kurzu
                cnt.isl.PevVzdelavaciKurzy.listPozadavkyKurz({ filters: { ixs_kurz: turnus.ixs_kur, aktivni: true } })
                    .getData()
                    .done((result) => {
                    absolvovaniKurzuDoplneni(cnt, ixs_esu_osoba, nazev_osoba, turnus, result, predchoziStavAbs, cnt.globalSettings?.get("Global.Pev.AppSettings.PovoleniKontrolaPropojeni") ?? false).then((pozadavky) => {
                        if (pozadavky != null) {
                            const guid_save = Gordic.Utils.generateGuid();
                            cnt.beginOperation({ id: guid_save, text: "jres:34900410" }); //RC 34900410 : Probíhá ukládání plnění plánu
                            const dto = {
                                turnus: turnus,
                                jenPozadavky: false,
                            };
                            const poz = [];
                            const pozPlan = [];
                            pozadavky.forEach((item) => {
                                poz.push(item.poz);
                                pozPlan.push(item.pozPlan);
                            });
                            cnt.isl.PevOsoba.savePlneniPlanuUcastOso({ turnus: turnus, pozadavky: poz, pozadavkyPlan: pozPlan, jenPozadavky: false })
                                .getData()
                                .done(() => {
                                //cnt.showFlash("Uloženo absolvování.", "success");
                                Per.WebControls.showSucess(cnt, "jres:34900408", "jres:34900075"); //RC 34900408 : Uložení absolvování
                                cnt.element.trigger("AbsolvovaniTurnusu");
                            })
                                .fail((xhr, type, vobj) => {
                                if (type === "exception") {
                                    if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                        vobj.handled = true;
                                        //cnt.showFlash(vobj.baseMessage, "error");
                                        Per.WebControls.showError(cnt, "jres:34900408", vobj.baseMessage); //RC 34900408 : Uložení absolvování
                                    }
                                }
                            })
                                .always(() => {
                                cnt.endOperation(guid_save);
                            });
                        }
                        else if (aktualizovatVzdy) {
                            cnt.element.trigger("AbsolvovaniTurnusu");
                        }
                    });
                })
                    .always(() => {
                    cnt.endOperation(guid);
                });
            }
            /**
             * Absolvování kurzu
             * @param cnt Content
             * @param ixs_esu_osoba Identifikátor osoby
             * @param nazev_osoba Název osoby
             * @param turnus DTO turnusu
             * @param pozadavkyKurz Seznam požadavků kurzu
             * @param predchoziStavAbs Předchozí stav absolvování
             * @param schvalPropoj Zda při absolvovaném turnusu připojovat neexistující požadavky
             */
            function absolvovaniKurzuDoplneni(cnt, ixs_esu_osoba, nazev_osoba, turnus, pozadavkyKurz, predchoziStavAbs, schvalPropoj) {
                const def_pozadavky = $.Deferred();
                const pozadavky = [];
                if (turnus == null || ixs_esu_osoba == null || nazev_osoba == null || pozadavkyKurz == null)
                    return def_pozadavky.resolve(null);
                const guid = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid, text: "jres:34900415" }); //RC 34900415 : Probíhá vyhodnocení požadavků osoby
                const PredchoziStavAbs = predchoziStavAbs == null ? 0 : predchoziStavAbs;
                let ZrusitAkci = false;
                const guid_pozPlan = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid_pozPlan, text: "jres:34900416" }); //RC 34900416 : Načítám plánované požadavky osoby
                cnt.isl.PevOsoba.listPozadavkyPlanOso({ filters: { ixs_esu: ixs_esu_osoba, aktivni: true } })
                    .getData()
                    .done((PozadavkyOsobaList) => {
                    pozadavkyKurz.forEach((kurzPozadavekDto) => {
                        let Rows = null;
                        if (PredchoziStavAbs !== 0) {
                            Rows = PozadavkyOsobaList.filter((r) => r.ixs_kvp === kurzPozadavekDto.ixs_kvp && r.ixs_kur === turnus.ixs_kur && r.poradi_kur === turnus.poradi)
                                .sort((a, b) => a.ixs_plv.localeCompare(b.ixs_plv))
                                .sort((a, b) => a.poradi - b.poradi);
                            if (Rows.length > 0) {
                                const pozadavekPlan = Rows[0];
                                if (turnus.stav_abs !== PredchoziStavAbs) {
                                    if (PredchoziStavAbs === 10) {
                                        if (turnus.stav_abs === 20) {
                                            switch (pozadavekPlan.ixs_hci_tspp) {
                                                case "0000BHR08Z2A": //splněn první náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z5V"; //nesplněn první náhradní
                                                    break;
                                                case "0000BHR08Z35": // splněn druhý náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z6Q"; //nesplněn druhý náhradní
                                                    break;
                                                case "0000BHR08Z1F": //splněn řádný termín
                                                case "0000BHR08Z0K": //neurčeno
                                                default:
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z40"; //nesplněn druhý náhradní
                                                    break;
                                            }
                                        }
                                        else if (turnus.stav_abs === 30) {
                                            switch (pozadavekPlan.ixs_hci_tspp) {
                                                case "0000BHR08Z2A": //splněn první náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z40"; //nesplněn řádný náhradní
                                                    break;
                                                case "0000BHR08Z35": // splněn druhý náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z5V"; //nesplněn první náhradní
                                                    break;
                                                case "0000BHR08Z1F": //splněn řádný termín
                                                default:
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z0K"; //neurčeno
                                                    break;
                                            }
                                        }
                                    }
                                    else if (PredchoziStavAbs === 20) {
                                        if (turnus.stav_abs == 10) {
                                            //z neuspesne na uspěšně
                                            switch (pozadavekPlan.ixs_hci_tspp) {
                                                case "0000BHR08Z5V": //nesplněn první náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z2A"; //první náhradní
                                                    break;
                                                case "0000BHR08Z6Q": //nesplněn druhý náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z35"; //druhý náhradní
                                                    break;
                                                case "0000BHR08Z40": //nesplněn řádný termín
                                                case "0000BHR08Z0K": //neurčeno
                                                default:
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z1F"; //řádný termín
                                                    break;
                                            }
                                        }
                                        else if (turnus.stav_abs == 30) {
                                            //z uspesne na nezúčastnil se
                                            switch (pozadavekPlan.ixs_hci_tspp) {
                                                case "0000BHR08Z5V": //nesplněn první náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z40"; //nesplněn řádný termín
                                                    break;
                                                case "0000BHR08Z6Q": //nesplněn druhý náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z5V"; //nesplněn první náhradní
                                                    break;
                                                case "0000BHR08Z40": //nesplněn řádný termín
                                                default:
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z0K"; //neurčeno
                                                    break;
                                            }
                                        }
                                    }
                                    else if (PredchoziStavAbs === 30) {
                                        //nemělo by nastat - u stavu=30 se nedělá záznam do pevsplp
                                        if (turnus.stav_abs == 10) {
                                            //z nezúčastnil se na uspěšně
                                            switch (pozadavekPlan.ixs_hci_tspp) {
                                                case "0000BHR08Z40": //nesplněn řádný termín
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z2A"; //první náhradní
                                                    break;
                                                case "0000BHR08Z5V": //nesplněn první náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z35"; //druhý náhradní
                                                    break;
                                                case "0000BHR08Z0K": //neurčeno
                                                default:
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z1F"; //řádný termín
                                                    break;
                                            }
                                        }
                                        else if (turnus.stav_abs == 20) {
                                            //z nezúčastnil se na neuspesne
                                            switch (pozadavekPlan.ixs_hci_tspp) {
                                                case "0000BHR08Z40": //nesplněn řádný termín
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z5V"; //nesplněn první náhradní
                                                    break;
                                                case "0000BHR08Z5V": //nesplněn první náhradní
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z6Q"; //nesplněn druhý náhradní
                                                    break;
                                                case "0000BHR08Z6Q": //nesplněn druhý náhradní - poslední stav nemělo by nastat
                                                    break;
                                                case "0000BHR08Z0K": //neurčeno
                                                default:
                                                    pozadavekPlan.ixs_hci_tspp = "0000BHR08Z40"; //nesplněn řádný termín
                                                    break;
                                            }
                                        }
                                    }
                                }
                                pozadavky.push({ poz: kurzPozadavekDto, pozPlan: pozadavekPlan });
                            }
                        }
                        if (PredchoziStavAbs === 0 || (schvalPropoj && (Rows == null || Rows.length === 0))) {
                            //turnus ještě nemá vazbu v plánu plnění
                            if (turnus.stav_abs !== 30) {
                                Rows = PozadavkyOsobaList.filter((r) => r.ixs_kvp === kurzPozadavekDto.ixs_kvp &&
                                    (r.ixs_hci_tspp == null || ["0000BHR08Z0K", "0000BHR08Z40", "0000BHR08Z5V"].includes(r.ixs_hci_tspp)))
                                    .sort((a, b) => a.ixs_plv.localeCompare(b.ixs_plv))
                                    .sort((a, b) => a.poradi - b.poradi);
                                if (Rows.length > 0) {
                                    const pozadavekPlan = Rows[0];
                                    pozadavekPlan.poradi_plp = null;
                                    if (turnus.stav_abs === 10) {
                                        switch (pozadavekPlan.ixs_hci_tspp) {
                                            case "0000BHR08Z40": //nesplněn řádný termín
                                                pozadavekPlan.ixs_hci_tspp = "0000BHR08Z2A"; //první náhradní
                                                break;
                                            case "0000BHR08Z5V": //nesplněn první náhradní
                                                pozadavekPlan.ixs_hci_tspp = "0000BHR08Z35"; //druhý náhradní
                                                break;
                                            case "0000BHR08Z0K": //neurčeno
                                            default:
                                                pozadavekPlan.ixs_hci_tspp = "0000BHR08Z1F"; //řádný termín
                                                break;
                                        }
                                    }
                                    else {
                                        switch (pozadavekPlan.ixs_hci_tspp) {
                                            case "0000BHR08Z40": //nesplněn řádný termín
                                                pozadavekPlan.ixs_hci_tspp = "0000BHR08Z5V"; //nesplněn první náhradní
                                                break;
                                            case "0000BHR08Z5V": //nesplněn první náhradní
                                                pozadavekPlan.ixs_hci_tspp = "0000BHR08Z6Q"; //nesplněn druhý náhradní
                                                break;
                                            case "0000BHR08Z6Q": //nesplněn druhý náhradní (poslední stav nemělo by nastat) - ošetřeno filtrem l_oRows = m_oldPozadavkyTable.Select ...
                                                break;
                                            case "0000BHR08Z0K": //neurčeno
                                            default:
                                                pozadavekPlan.ixs_hci_tspp = "0000BHR08Z40"; //nesplněn řádný termín
                                                break;
                                        }
                                    }
                                    pozadavky.push({ poz: kurzPozadavekDto, pozPlan: pozadavekPlan });
                                }
                                else {
                                    pozadavky.push({ poz: kurzPozadavekDto, pozPlan: null });
                                }
                            } //end if
                        } //end if
                    }); //end foreach
                    const def_prednacteni = $.Deferred();
                    let PlanyOsobyList = null;
                    //přednačtení plánů, pokud v požadavcích je value null
                    if (pozadavky.map((r) => r.pozPlan).includes(null)) {
                        const guid_planOso = Gordic.Utils.generateGuid();
                        cnt.beginOperation({ id: guid_planOso, text: "jres:34900417" }); //RC 34900417 : Načítám plány osoby
                        cnt.isl.PevOsoba.listPlanOsoby({ filters: { ixs_esu: ixs_esu_osoba, aktivni: true } })
                            .getData()
                            .done((result) => {
                            PlanyOsobyList = result;
                            const datum = new Date();
                            if (result.filter((r) => (r.dat_od == null || parseDate(r.dat_od).getTime() <= datum.getTime()) &&
                                (r.dat_do == null || parseDate(r.dat_do).getTime() >= datum.getTime())).length === 0) {
                                if (!cnt["ParametrPevRadEvidVzdPlanu"]) {
                                    //vytvořit plán a znovu načíst
                                    createPlanOso(cnt, ixs_esu_osoba)?.then(() => {
                                        cnt.isl.PevOsoba.listPlanOsoby({ filters: { ixs_esu: ixs_esu_osoba, aktivni: true } })
                                            .getData()
                                            .done((plany) => {
                                            PlanyOsobyList = plany;
                                            def_prednacteni.resolve(true);
                                        });
                                    });
                                }
                            }
                            else
                                def_prednacteni.resolve(true);
                        })
                            .always(() => {
                            cnt.endOperation(guid_planOso);
                        });
                    }
                    else
                        def_prednacteni.resolve(false);
                    def_prednacteni.then(async (prochazetPoz) => {
                        if (prochazetPoz) {
                            //pokud pozadavky nemají ve value null, je zbytečný procházet celý pole
                            const prvkyKOdstraneni = [];
                            for (let i = 0; i < pozadavky.length; i++) {
                                const item = pozadavky[i];
                                if (item.pozPlan == null) {
                                    let jeVPlanu = true;
                                    if (cnt["ParametrPevAutoPozDoPlanu"]) {
                                        jeVPlanu = PozadavkyOsobaList.filter((r) => r.ixs_kvp === item.poz.ixs_kvp).length > 0;
                                    }
                                    if (jeVPlanu) {
                                        //čekej na výběr uživatele
                                        const aktDatum = new Date();
                                        const pozadavky = PozadavkyOsobaList.filter((r) => r.ixs_kvp === item.poz.ixs_kvp);
                                        const plany = PlanyOsobyList?.filter((r) => (r.dat_od == null ? aktDatum.getTime() : parseDate(r.dat_od).getTime()) <= aktDatum.getTime() &&
                                            (r.dat_do == null ? aktDatum.getTime() : parseDate(r.dat_do).getTime()) >= aktDatum.getTime());
                                        await showVyberPozAbsolvovani(cnt, pozadavky, plany, item.poz, ixs_esu_osoba, nazev_osoba, turnus.stav_abs).then((result) => {
                                            if (result != null) {
                                                if (result.VybranyPozadavek.ixs_plv == null) {
                                                    //odstranit prvek
                                                    prvkyKOdstraneni.push(item);
                                                }
                                                else {
                                                    item.pozPlan = result.VybranyPozadavek;
                                                }
                                            }
                                            else {
                                                ZrusitAkci = true;
                                            }
                                        });
                                        if (ZrusitAkci)
                                            break;
                                    }
                                    else {
                                        //pokud mám plán, automaticky vložím
                                        const aktDatum = new Date();
                                        const planyRows = PlanyOsobyList?.filter((r) => (r.dat_od == null || parseDate(r.dat_od).getTime() <= aktDatum.getTime()) &&
                                            (r.dat_do == null || parseDate(r.dat_do).getTime() >= aktDatum.getTime()));
                                        if (planyRows.length > 0) {
                                            const newPozadavek = {
                                                ixs_plv: planyRows[0].ixs_plv,
                                                ixs_kvp: item.poz.ixs_kvp,
                                                pozadavek_nazev: item.poz.nazev?.trim(),
                                                pozadavek_zkratka: item.poz.zkratka?.trim(),
                                                ixs_hci_drsp: item.poz.ixs_hci_drsp,
                                                ixs_hci_drsp_txt: item.poz.ixs_hci_drsp_txt?.trim(),
                                                ixs_esu: ixs_esu_osoba,
                                                priz_opak: 0,
                                                poc_mes_opak: 0,
                                                poc_rok_opak: 0,
                                                poznamka: "Vytvořeno absolvováním kurzu dne {0}.".format(aktDatum.toLocaleDateString("cs")),
                                                ixs_hci_tspp: turnus.stav_abs == 10 ? "0000BHR08Z1F" : "0000BHR08Z40",
                                            };
                                            item.pozPlan = newPozadavek;
                                        }
                                        else {
                                            //odstranění požadavku
                                            prvkyKOdstraneni.push(item);
                                        }
                                    } //end else
                                } //end if
                            } //end for
                            if (prvkyKOdstraneni.length !== 0) {
                                prvkyKOdstraneni.forEach((item) => {
                                    const i = pozadavky.indexOf(item);
                                    if (i != -1)
                                        pozadavky.splice(i, 1);
                                });
                            }
                        }
                        cnt.endOperation(guid);
                        if (ZrusitAkci)
                            def_pozadavky.resolve(null);
                        def_pozadavky.resolve(pozadavky);
                        return null;
                    });
                })
                    .always(() => {
                    cnt.endOperation(guid_pozPlan);
                });
                //return pozadavky;
                return def_pozadavky.promise();
            }
            /**
             * Zobrazení okna GVyberPozAbsolvovani a čekání na výběr uživatele
             * @param cnt
             */
            function showVyberPozAbsolvovani(cnt, pozadavky, plany, pozadavek, ixs_esu_osoba, nazev_osoba, stav) {
                const def = $.Deferred();
                cnt.dialogs
                    .showWindow("Gordic.Pev.WebClient.GVyberPozAbsolvovani", {
                    Pozadavek: pozadavek,
                    IxsEsu: ixs_esu_osoba,
                    NazevEsu: nazev_osoba,
                    Stav: stav,
                    Pozadavky: pozadavky,
                    Plany: plany,
                }, `Výběr požadavku ze vzdělávacího plánu osoby ${nazev_osoba}`, 800, 550)
                    .on("close", (ev, result) => {
                    def.resolve(result);
                });
                return def.promise();
            }
            /**
             * PEV - Zobrazení o absolvování kurzu
             * @param cnt Content
             * @param osoba DTO osoby
             * @param turnus DTO turnusu
             */
            function absolvovaniKurzuDetail(cnt, osoba, turnus) {
                if (turnus == null || osoba == null || osoba.ixs_esu == null)
                    return;
                absolvovaniKurzuDetailx(cnt, osoba, turnus, null, null, null);
            }
            WebControls.absolvovaniKurzuDetail = absolvovaniKurzuDetail;
            /**
             * PEV - Absolvování kurzu/turnusu osobami
             */
            function absolvovaniKurzuOsoby(cnt, turnus, pocet_osob, rozsah_dny, rozsah_hod, uspesni, ostatni) {
                if (cnt == null || turnus == null || ((uspesni == null || uspesni.length === 0) && (ostatni == null || ostatni.length === 0)))
                    return;
                cnt.navigate("Gordic.Pev.WebClient.GVyberZamAbs", {
                    Uspesni: uspesni,
                    Ostatni: ostatni,
                }).on("close", (ev, res) => {
                    if (res != null) {
                        if (res.uspesni.length > 0 || res.neucast.length > 0 || res.neuspesni.length > 0) {
                            const newTurnus = {
                                ixs_kur: turnus.ixs_kur,
                                poradi: turnus.poradi,
                                stav_abs: res.uspesni.length > 0 ? 10 : res.neuspesni.length > 0 ? 20 : res.neucast.length > 0 ? 30 : 0,
                                doklad_nazev: null,
                                doklad_cislo: null,
                                doklad_vydal: null,
                                poznamka_zar: null,
                                pocet_osob: pocet_osob == null ? 0 : pocet_osob,
                                rozsah_dny: rozsah_dny == null ? new Decimal(0) : rozsah_dny,
                                rozsah_hod: rozsah_hod == null ? new Decimal(0) : rozsah_hod,
                                stav_uc: 30,
                                c_cest_uc: new Decimal(0),
                                proc_spol_uc: new Decimal(0),
                                c_spol_uc: new Decimal(0),
                                kod: turnus.kod,
                                kod_kurz: turnus.kod_kurz,
                                nazev_kurz: turnus.nazev_kurz,
                                zkratka_kurz: turnus.zkratka_kurz,
                                dat_od: turnus.dat_od,
                                dat_do: turnus.dat_do,
                                dat_uzav: turnus.dat_uzav,
                                max_pocet: turnus.max_pocet,
                                misto: turnus.misto,
                                ucebna: turnus.ucebna,
                                ixs_esu_org: turnus.ixs_esu_org,
                                c_celk: turnus.c_celk,
                                c_jed: turnus.c_jed,
                                c_mat: turnus.c_mat,
                                stav: turnus.stav,
                                stav_txt: turnus.stav_txt,
                                prubeh: turnus.prubeh,
                                prubeh_txt: turnus.prubeh_txt,
                                ac_fak: turnus.ac_fak,
                                ac_obj: turnus.ac_obj,
                                poznamka_turnus: turnus.poznamka,
                            };
                            absolvovaniKurzuDetailx(cnt, null, newTurnus, res.uspesni, res.neuspesni, res.neucast);
                        }
                    }
                });
            }
            WebControls.absolvovaniKurzuOsoby = absolvovaniKurzuOsoby;
            /**
             * PEV - Splnění požadavku
             * @param cnt
             * @param ixs_esu
             * @param nazev_osoba
             * @param ixs_kur
             * @param poradi_kur
             * @param pozadavek
             * @returns
             */
            function absolvovaniPozadavekKurz(cnt, ixs_esu, nazev_osoba, ixs_kur, poradi_kur, pozadavek) {
                if (ixs_esu == null || ixs_kur == null || poradi_kur == null || pozadavek == null)
                    return;
                const guid = Gordic.Utils.generateGuid();
                cnt.beginOperation({ id: guid, text: "jres:34900076" }); //RC 34900076 : Načítám kurz
                cnt.isl.PevOsoba.listKurzOsoby({ filters: { ixs_esu: ixs_esu, aktivni: true } })
                    .getData()
                    .done((turnusyList) => {
                    const rows = turnusyList.filter((r) => r.ixs_kur === ixs_kur && r.poradi === poradi_kur);
                    if (rows.length === 0)
                        return;
                    const turnus = rows[0];
                    const pozadavkyKurz = [];
                    pozadavkyKurz.push(pozadavek);
                    absolvovaniKurzuDoplneni(cnt, ixs_esu, nazev_osoba, turnus, pozadavkyKurz, turnus.stav_abs, true).then((pozadavky) => {
                        if (pozadavky != null && pozadavky.length > 0) {
                            const poz = [];
                            const pozPlan = [];
                            pozadavky.forEach((item) => {
                                poz.push(item.poz);
                                pozPlan.push(item.pozPlan);
                            });
                            const guid_save = Gordic.Utils.generateGuid();
                            cnt.beginOperation({ id: guid_save, text: "jres:34900418" }); //RC 34900418 : Probíhá ukládání absolvování požadavku
                            cnt.isl.PevOsoba.savePlneniPlanuUcastOso({
                                turnus: turnus,
                                pozadavky: poz,
                                pozadavkyPlan: pozPlan,
                                jenPozadavky: true,
                            })
                                .getData()
                                .done(() => {
                                cnt.element.trigger("AbsolvovaniTurnusu");
                            })
                                .fail((xhr, type, vobj) => {
                                if (type === "exception") {
                                    if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                        vobj.handled = true;
                                        //cnt.showFlash(vobj.baseMessage, "error");
                                        Per.WebControls.showError(cnt, "jres:34900419", vobj.baseMessage); //RC 34900419 : Uložení absolvování požadavku
                                    }
                                }
                            })
                                .always(() => {
                                cnt.endOperation(guid_save);
                            });
                        }
                    });
                });
            }
            WebControls.absolvovaniPozadavekKurz = absolvovaniPozadavekKurz;
            /** PEV - Zrušení absolvování turnusu */
            function cancelSplneniKurzu(cnt, turnusOsoby) {
                if (!(cnt["DebugMode"] || cnt["ParametrPevRadPovMaz"]) ||
                    turnusOsoby == null ||
                    turnusOsoby.ixs_esu == null ||
                    turnusOsoby.ixs_kur == null ||
                    turnusOsoby.poradi == null) {
                    return;
                }
                cnt.dialogs
                    .confirm("jres:34900042", "jres:34900420") //RC 34900420 : Opravdu chcete zrušit absolvování turnusu?
                    .on("yes", () => {
                    const guid = Gordic.Utils.generateGuid();
                    cnt.beginOperation({ id: guid, text: "jres:34900421" }); //RC 34900421 : Probíhá rušení absolvování turnusu
                    cnt.isl.PevOsoba.cancelAbs({ ixs_esu: turnusOsoby.ixs_esu, ixs_kur: turnusOsoby.ixs_kur, poradi: turnusOsoby.poradi })
                        .getData()
                        .done(() => {
                        //cnt.showFlash("Absolvování zrušeno.", "success");
                        Per.WebControls.showSucess(cnt, "jres:34900422", "jres:34900371"); //RC 34900422 : Rušení absolvování turnusu
                        cnt.element.trigger("AbsolvovaniTurnusu");
                    })
                        .fail((xhr, type, vobj) => {
                        if (type === "exception") {
                            if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                vobj.handled = true;
                                //cnt.showFlash(vobj.baseMessage, "error");
                                Per.WebControls.showError(cnt, "jres:34900422", vobj.baseMessage);
                            }
                        }
                    })
                        .always(() => {
                        cnt.endOperation(guid);
                    });
                });
            }
            WebControls.cancelSplneniKurzu = cancelSplneniKurzu;
            //#endregion Absolvování
        })(WebControls = Per.WebControls || (Per.WebControls = {}));
    })(Per = Gordic.Per || (Gordic.Per = {}));
})(Gordic || (Gordic = {}));
