                loadListPlany() {
                    const content = this;
                    const def = $.Deferred();
                    const guid_plany = Gordic.Utils.generateGuid();
                    content.beginOperation({ id: guid_plany, text: "jres:34900100" }); //RC 34900100 : Načítám vzdělávací plány
                    content.isl.PevOsoba.listPlanOsoby({ filters: { ixs_esu: content.IxsEsu, datum: null, aktivni: true } })
                        .getData()
                        .done((result) => {
                        content.planOsobyList = result;
                        def.resolve();
                    })
                        .always(() => {
                        content.endOperation(guid_plany);
                    });
                    return def.promise();
                }
                getVek(narozeni) {
                    const vek = 0;
                    if (narozeni != null) {
                        const dnes = new Date();
                        const datumNarozeni = new Date(narozeni.toString());
                        // Rozdíl mezi aktuálním datem a datem narození
                        const rozdil = dnes.getTime() - datumNarozeni.getTime();
                        // Převod rozdílu na věk
                        const vekVmilisekundach = rozdil;
                        const vekVRoce = vekVmilisekundach / (1000 * 60 * 60 * 24 * 365.25); // Přičítáme 0.25 pro přestupné roky
                        return Math.floor(vekVRoce);
                    }
                    return vek;
                }
