                newData() {
                    const content = this;
                    if (content.DtoTurnus == null || content.DtoTurnus.ixs_kur == null) {
                        content.DtoTurnus = {};
                        content.dialogs.error("jres:29120102", "jres:34900313"); //RC 34900313 : Nebyl vybrán vzdělávací kurz.
                        content.readOnly = true;
                        content.setDisabled(null, 0);
                    }
                    content.DtoTurnus.c_celk = new Decimal(0);
                    content.DtoTurnus.c_plan = new Decimal(0);
                    content.DtoTurnus.c_jed = new Decimal(0);
                    content.DtoTurnus.c_mat = new Decimal(0);
                    content.DtoTurnus.stav = 10;
                    //Content.DtoTurnus.ixs_esu_org = kurz.ixs_esu;
                    //#region Zjištění existence generace
                    if (content.DtoTurnus != null && content.DtoTurnus.ixs_kur != null && content.DtoTurnus.poradi != null) {
                        const guid_gen = Gordic.Utils.generateGuid();
                        content.beginOperation({ id: guid_gen, text: "jres:34900314" }); //RC 34900314 : Zjišťuji existenci generace
                        content.isl.PevVzdelavaciKurzy.existujeGeneraceTur({ ixs_kur: content.DtoTurnus.ixs_kur, poradi: content.DtoTurnus.poradi })
                            .get()
                            .done((result) => {
                            content.maTurnusGeneraci = result;
                        })
                            .fail((xhr, type, vobj) => {
                            if (type === "exception") {
                                if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                    vobj.handled = true;
                                    //Content.showFlash(vobj.baseMessage, "error");
                                    Per.WebControls.showError(content, "jres:34900315", vobj.baseMessage); //RC 34900315 : Existence generace
                                }
                            }
                        })
                            .always(() => {
                            content.endOperation(guid_gen);
                        });
                    }
                    //#endregion Zjištění existence generace
                    content.findFields().gfield("model", "apply", content.DtoTurnus, { initialValues: true });
                    content.findFields("cena_tur").gfield("setValue", 0);
                    content.actions.act_LoadOso.run();
                    content.actions.act_LoadLek.run();
                }
                loadData() {
                    const content = this;
                    const def_tur = $.Deferred();
                    if (content.DtoTurnus == null && content.IxsKur != null && content.Poradi != null) {
                        const guid = Gordic.Utils.generateGuid();
                        content.beginOperation({ id: guid, text: "jres:34900063" }); //RC 34900063 : Načítám turnus
                        content.isl.PevVzdelavaciKurzy.readTurnus({ ixs_kur: content.IxsKur, poradi: content.Poradi })
                            .getData()
                            .done((dto) => {
                            content.DtoTurnus = dto;
                            def_tur.resolve();
                        })
                            .fail((xhr, type, vobj) => {
                            if (type === "exception") {
                                if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                    vobj.handled = true;
                                    //Content.showFlash(vobj.baseMessage, "error");
                                    Per.WebControls.showError(content, "jres:34900316", vobj.baseMessage); //RC 34900316 : Načtení turnusu
                                }
                            }
                        })
                            .always(() => {
                            content.endOperation(guid);
                        });
                    }
                    else if (content.DtoTurnus != null && content.DtoTurnus.ixs_kur != null)
                        def_tur.resolve();
                    else {
                        content.dialogs.error("jres:29120102", "jres:34900313"); //RC 34900313 : Nebyl vybrán vzdělávací kurz.
                        content.readOnly = true;
                        content.setDisabled(null, 0);
                        return;
                    }
                    def_tur.then(() => {
                        //#region Zjištění existence generace
                        const guid_gen = Gordic.Utils.generateGuid();
                        content.beginOperation({ id: guid_gen, text: "jres:34900314" }); //RC 34900314 : Zjišťuji existenci generace
                        content.isl.PevVzdelavaciKurzy.existujeGeneraceTur({ ixs_kur: content.DtoTurnus.ixs_kur, poradi: content.DtoTurnus.poradi })
                            .get()
                            .done((result) => {
                            content.maTurnusGeneraci = result;
                        })
                            .fail((xhr, type, vobj) => {
                            if (type === "exception") {
                                if (vobj.baseType === "Gordic.General.GNonFatalException" || vobj.baseType === "Gordic.General.GArgumentNullException") {
                                    vobj.handled = true;
                                    //Content.showFlash(vobj.baseMessage, "error");
                                    Per.WebControls.showError(content, "jres:34900315", vobj.baseMessage); //RC 34921222 : Existence generace
                                }
                            }
                        })
                            .always(() => {
                            content.endOperation(guid_gen);
                        });
                        //#endregion Zjištění existence generace
                        content.findFields().gfield("model", "apply", content.DtoTurnus, { initialValues: true });
                        //Content.findFields("cena_tur").gfield("setValue", (Content.DtoTurnus.c_celk != null && parseDecimal(Content.DtoTurnus.c_celk).greaterThan(0)) ? 1 : 0);
                        /*Content.findFields("cena_tur").gfield("getValueAsync").then(() => {
                            Content.findFields("cena_tur").gfield("setValue", (Content.DtoTurnus.c_celk != null && parseDecimal(Content.DtoTurnus.c_celk).greaterThan(0)) ? 1 : 0);
                        });*/
                        content.actions.act_LoadOso.run();
                        content.actions.act_LoadLek.run();
                        if (content.ZobrazPozadavky)
                            content.actions.act_LoadPoz.run();
                        content
                            .findFields("stav")
                            .gfield("getValueAsync")
                            .then((value_stav) => {
                            content
                                .findFields("max_pocet")
                                .gfield("getValueAsync")
                                .then((value_pocet) => {
                                content.setDisabled(value_stav == null ? null : value_stav.stav, value_pocet);
                            });
                        });
                    });
                }
